import{_ as t,o as s,c as a,ag as n}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Database Schema Overview","description":"","frontmatter":{},"headers":[],"relativePath":"reference/schema/index.md","filePath":"reference/schema/index.md"}'),i={name:"reference/schema/index.md"};function d(o,e,r,l,p,c){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="database-schema-overview" tabindex="-1">Database Schema Overview <a class="header-anchor" href="#database-schema-overview" aria-label="Permalink to &quot;Database Schema Overview&quot;">​</a></h1><p>VERA&#39;s data lives in <strong>Postgres</strong> (Supabase). Every tenant&#39;s rows are isolated with row-level security keyed off a <code>tenant_id</code> UUID set per request via <code>SET LOCAL app.tenant_id</code>. The bot reads and writes exclusively through the DAL (<code>lib/dal.js</code>) so RLS scoping is uniform across every code path.</p><hr><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th><th>Key operations</th></tr></thead><tbody><tr><td><code>time_entries</code></td><td>Every logged hour</td><td>INSERT, UPDATE, DELETE</td></tr><tr><td><code>projects</code></td><td>Project definitions (parents + period/sprint children)</td><td>INSERT, per-column UPDATE</td></tr><tr><td><code>users</code></td><td>Team members</td><td>INSERT, UPDATE role/status</td></tr><tr><td><code>clients</code></td><td>Client organisations</td><td>INSERT, UPDATE name/status</td></tr><tr><td><code>tasks</code></td><td>Work categories</td><td>INSERT, UPDATE name</td></tr><tr><td><code>project_tasks</code></td><td>Tasks enabled per project</td><td>INSERT (enable), DELETE (disable)</td></tr><tr><td><code>budgets</code></td><td>Per-person hour envelopes</td><td>INSERT, UPDATE hours/status/task</td></tr><tr><td><code>disciplines</code></td><td>Functional roles</td><td>INSERT, UPDATE name/status</td></tr><tr><td><code>conversations</code></td><td>24-hour chat history; <code>entities</code> JSONB column holds typed entity references from each turn&#39;s tool calls</td><td>INSERT</td></tr><tr><td><code>pending_pto</code></td><td>Time off requests</td><td>INSERT, UPDATE approval/rejection</td></tr><tr><td><code>unresolved_items</code></td><td>Flagged operational issues</td><td>INSERT, UPDATE status</td></tr><tr><td><code>company_calendar</code></td><td>Holidays and events</td><td>INSERT, DELETE</td></tr><tr><td><code>rate_history</code></td><td>Hourly cost per person (versioned)</td><td>INSERT only</td></tr><tr><td><code>liabilities</code></td><td>Vendor payment commitments</td><td>INSERT, UPDATE status</td></tr></tbody></table><p>Definitive column-by-column shape lives in the migration files (<code>migrations/*.js</code>). The DAL reader functions in <code>lib/dal.postgres.js</code> project each table into the object shape callers consume.</p><hr><h2 id="tenant-isolation" tabindex="-1">Tenant isolation <a class="header-anchor" href="#tenant-isolation" aria-label="Permalink to &quot;Tenant isolation&quot;">​</a></h2><p>Every connection enters a <code>withTenant(callback)</code> block that opens a transaction and runs:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LOCAL</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tenant_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;tenant uuid&gt;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The runtime role <code>vera_app</code> is <code>NOBYPASSRLS</code>, so policies on every table filter <code>tenant_id = current_setting(&#39;app.tenant_id&#39;)::uuid</code> automatically. Application code never filters by tenant — RLS does it. A query that &quot;forgets&quot; to scope still returns only the current tenant&#39;s rows.</p><p>The privileged <code>postgres</code> role (set via <code>MIGRATION_DATABASE_URL</code>) bypasses RLS and is used only by migrations.</p><hr><h2 id="id-strategy" tabindex="-1">ID strategy <a class="header-anchor" href="#id-strategy" aria-label="Permalink to &quot;ID strategy&quot;">​</a></h2><p>Per-tenant integer IDs are computed at write time as <code>MAX(existing) + 1</code> within the tenant. IDs are <strong>permanent and sequential within a tenant</strong> — never reused, even when records are deleted. Time entry <code>#42</code> always refers to the same entry, enabling reliable audit trails and edit/delete operations via natural language.</p><hr><h2 id="foreign-keys" tabindex="-1">Foreign keys <a class="header-anchor" href="#foreign-keys" aria-label="Permalink to &quot;Foreign keys&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>users ──┬── user_id          ─→ time_entries, budgets, pending_pto, rate_history</span></span>
<span class="line"><span>        ├── pm_user_id       ─→ projects</span></span>
<span class="line"><span>        ├── discipline_id    ─→ disciplines</span></span>
<span class="line"><span>        ├── created_by       ─→ budgets, liabilities</span></span>
<span class="line"><span>        ├── vendor_user_id   ─→ liabilities</span></span>
<span class="line"><span>        └── affected_user_id ─→ unresolved_items</span></span>
<span class="line"><span></span></span>
<span class="line"><span>projects ──┬── project_id       ─→ time_entries, project_tasks, budgets</span></span>
<span class="line"><span>           ├── client_id        ─→ clients</span></span>
<span class="line"><span>           ├── parent_project_id ─→ projects (self-ref, periods/sprints)</span></span>
<span class="line"><span>           └── affected_project_id ─→ unresolved_items</span></span>
<span class="line"><span></span></span>
<span class="line"><span>clients ──── client_id ─→ projects</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tasks ──┬── task_id ─→ time_entries, project_tasks, budgets</span></span></code></pre></div><hr><h2 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h2><p>Schema is managed by <code>node-pg-migrate</code> (<code>migrations/</code> directory). To apply pending migrations locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:up</span></span></code></pre></div><p>In production this runs automatically on boot via <code>scripts/start.js</code> when <code>MIGRATION_DATABASE_URL</code> is set. An applied migration is recorded in the <code>pgmigrations</code> bookkeeping table; re-running is idempotent.</p><p>For schema changes:</p><ol><li>Create the migration: <code>npx node-pg-migrate create &lt;descriptive_name&gt;</code></li><li>Implement <code>up</code> and <code>down</code></li><li>Apply locally: <code>npm run migrate:up</code></li><li>Update the relevant reader in <code>lib/dal.postgres.js</code> and the typed updater (if applicable)</li><li>Add or update tests in <code>tests/mcp-routes.test.js</code> and <code>tests/dal-postgres.test.js</code></li><li>Update this doc if a new table or relationship was introduced</li></ol>`,25)])])}const g=t(i,[["render",d]]);export{u as __pageData,g as default};
